const bad = [];
function big(cents, percent) {
  const scaled = BigInt(cents) * BigInt(percent);
  return Number((scaled + 50n) / 100n);
}
for (let p of [1, 2]) {
  for (let n = 0; n <= 2_000_000; n++) {
    const a = Math.round(n * (p / 100));
    const b = Math.round((n * p) / 100);
    const c = Math.floor((n * p + 50) / 100);
    const d = big(n, p);
    if (a !== d || b !== d || c !== d) bad.push([n, p, a, b, c, d]);
  }
}
console.log("mismatches", bad.length);
console.log(bad.slice(0, 20));
'
